// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from (actor), value v, single recipient to ensure exactly one call
    function testFuzz_property(address from, uint256 v, address /*unused placeholder to ensure three params*/) public {
        // keep recipient array length == 1 to make observation simple
        address[] memory tos = new address[](1);
        // deploy a recorder that implements transferFrom(address,address,uint256)
        Recorder r = new Recorder();
        tos[0] = address(r);

        // ensure non-zero length requirement satisfied (already 1)
        // Call transfer via try/catch to observe revert behavior if any
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general fact we assert: the recorder must have recorded exactly one call
        // with selector corresponding to transferFrom(address,address,uint256).
        // The correct contract always encodes & sends that selector and arguments,
        // so recorder.decodedCallCount() == 1 for all admissible inputs.
        // The mutant that uses caddress.call("") will NOT supply that selector/ABI
        // and the recorder will not decode such a call as transferFrom — causing count==0.
        assertTrue(r.decodedCallCount() == 1);
    }
}

// Recorder implements the exact function signature so that abi.decode works when selector is present.
contract Recorder {
    // count of successfully decoded transferFrom calls
    uint256 public decodedCount;
    // stored last arguments for inspection (not used in assertion beyond count)
    address public last_from;
    address public last_to;
    uint256 public last_v;

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        decodedCount += 1;
        last_from = from;
        last_to = to;
        last_v = v;
        return true;
    }

    // fallback to record malformed/empty calldata; does nothing so malformed calls don't increase decodedCount
    fallback() external payable {
        // intentionally left blank: malformed or empty calldata will hit fallback and not increment decodedCount
    }

    receive() external payable {
        // accept plain ETH sends if any
    }

    function decodedCallCount() external view returns (uint256) {
        return decodedCount;
    }
}
